const products=[{id:'amara',name:'Amara Draped Dress',price:189000,category:'Dresses',colour:'Burgundy',badge:'New'},{id:'zuri',name:'Zuri Two-Piece Set',price:165000,category:'Sets & Tops',colour:'Sage',badge:'Bestseller'},{id:'nia',name:'Nia Statement Dress',price:210000,category:'Occasions',colour:'Ivory',badge:'Trending'},{id:'lola',name:'Lola Corset Top',price:120000,category:'Sets & Tops',colour:'Navy',badge:''},{id:'kemi',name:'Kemi Maxi Dress',price:175000,category:'Dresses',colour:'Amber',badge:'New'}];
const colours={Burgundy:'#681128',Ivory:'#e5d8c7',Sage:'#8ea58a',Navy:'#172b50',Amber:'#c98d35'};const sizes=['XS','S','M','L','XL'];const money=n=>'₦'+Number(n).toLocaleString('en-NG');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const read=(k,f)=>{try{return JSON.parse(localStorage.getItem('velmora-'+k))??f}catch{return f}};const state={bag:read('bag',[]),saved:read('saved',[]),refs:read('refs',[]),prefs:read('prefs',{colours:['Burgundy','Ivory','Emerald'],style:'Elegant & classic',size:'M',fit:'Fitted'}),lab:read('lab',{occasion:'Wedding',fit:'Fitted',style:'Elegant & classic',setting:'Indoor',budget:200000,request:''}),selected:'amara',size:'M',colour:'Burgundy',category:'All',sort:'Featured',search:'',maxPrice:250000,filterSize:'',filterColour:'',photo:null,estimate:'M',bust:88,waist:72,order:read('order',null),messages:[]};let route='home',param='';const persist=k=>localStorage.setItem('velmora-'+k,JSON.stringify(state[k]));const pby=id=>products.find(p=>p.id===id)||products[0];const image=p=>'/assets/'+p.id+'.jpg';const tall=p=>image(p);const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${({heart:'<path d="M20 4c-3-3-7 0-8 3-1-3-5-6-8-3-5 5 8 15 8 15S25 9 20 4Z"/>',bag:'<rect x="5" y="6" width="14" height="15" rx="2"/><path d="M9 7V5a3 3 0 0 1 6 0v2"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',diamond:'<path d="m12 3 9 9-9 9-9-9Z"/>',home:'<path d="m3 11 9-8 9 8M5 10v11h14V10M10 21v-7h4v7"/>',journal:'<rect x="4" y="3" width="16" height="18" rx="1"/><path d="M8 7h8M8 11h8M8 15h5"/>',person:'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>'})[n]||''}</svg>`;const link=(text,to,cls='')=>`<a href="#/${to}" class="${cls}">${text}</a>`;const btn=(text,to,cls='')=>link(text,to,'btn '+cls);const action=(text,name,extra='',cls='')=>`<button data-action="${name}" ${extra} class="${cls}">${text}</button>`;const heading=(title,sub='')=>`<div class="heading"><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>`;const grid=(ps,cls='',mode='')=>`<div class="products ${cls}">${ps.map(p=>card(p,mode)).join('')}</div>`;
function card(p,mode=''){return `<article class="card"><div class="card-image">${link(`<img src="${image(p)}" alt="${p.name}" loading="lazy">`,'product/'+p.id)}${action(state.saved.includes(p.id)?'♥':'♡','save',`data-id="${p.id}" aria-label="${state.saved.includes(p.id)?'Unsave':'Save'} ${p.name}" aria-pressed="${state.saved.includes(p.id)}"`,'heart')}${p.badge?`<span class="badge ${p.badge==='Trending'?'trending':''}">${p.badge}</span>`:''}</div>${link(`<h3>${p.name}</h3>`,'product/'+p.id)}<div class="price">${money(p.price)}</div>${mode==='select'?action('Choose','choose',`data-id="${p.id}"`,'btn small light'):mode==='saved'?`<div class="actions">${action('Add to Bag','add',`data-id="${p.id}"`,'btn small')}${action('Remove','save',`data-id="${p.id}"`,'text-link')}</div>`:mode==='view'?btn('View piece','product/'+p.id,'small'):mode==='refs'?action('Remove reference','reference',`data-id="${p.id}"`,'text-link'):`<div class="dots"><span style="background:#681128"></span><span style="background:#dbc2a3"></span><span style="background:#202020"></span></div>`}</article>`}
function navLinks(){return [['New In','shop/New'],['Shop','shop'],['Dresses','shop/Dresses'],['Sets & Tops','shop/Sets & Tops'],['Occasions','shop/Occasions'],['Style Gallery','gallery'],['Journal','journal']].map(([t,r])=>link(t,r,(route===r.split('/')[0] && (route!=='shop' || decodeURIComponent(param||'')===r.split('/').slice(1).join('/')))?'active':'')).join('')}
const titles={gallery:'Style Gallery',journal:'Journal',article:'Journal',runway:'Runway',chat:'Verola Chat',lab:'Fashion Lab','lab-budget':'Fashion Lab','lab-results':'Fashion Lab',estimate:'Size Estimate','estimate-result':'Size Estimate',photo:'Photo Comparison',compare:'Photo Comparison',colour:'Colour Preview',studio:'Outfit Studio',closet:'My Closet',preferences:'My Closet',saved:'Saved Pieces',select:'Select Garment',look:'Wedding Guest','look-preview':'Photo Preview'};
function shell(content){const count=state.bag.reduce((s,i)=>s+i.qty,0),bottom=['home','shop','saved','journal','closet'].includes(route);return `<div class="topbar"><span>Free delivery across Nigeria on orders ₦150,000+</span><div>${link('Help','chat')}${link('Track order','order-status')}${link('Delivery & Returns','delivery')}</div></div><header>${action(icon('menu'),'menu','aria-label="Open navigation"','mobile-menu')}<a href="#/home" class="brand ${titles[route]?'desktop-only':''}">ZARELLE</a>${titles[route]?`<div class="mobile-title">${titles[route]}</div>`:''}<nav>${navLinks()}</nav><form id="search-form"><input class="search" name="search" aria-label="Search products" placeholder="Search products…" value="${esc(state.search)}"></form><div class="icons">${link(icon('heart'),'saved','icon')}${link(icon('diamond'),'chat','icon desktop-only')}${link(icon('bag')+(count?`<span class="count">${count}</span>`:''),'bag','icon')}</div></header><main id="main" tabindex="-1">${content}</main>${bottom?`<nav class="bottom-nav" aria-label="Mobile navigation">${[['Home','home','home'],['Shop','shop','bag'],['Saved','saved','heart'],['Journal','journal','journal'],['My Closet','closet','person']].map(([t,r,i])=>link(icon(i)+t,r,route===r?'active':'')).join('')}</nav>`:''}<footer class="footer"><span>© ${new Date().getFullYear()} ZARELLE</span><nav>${link('Runway','runway')}${link('Fashion Lab','lab')}${link('Size Estimate','estimate')}${link('Photo Comparison','photo')}${link('Outfit Studio','studio')}${link('My Closet','closet')}</nav></footer>`}
function home(){return `<section class="hero"><picture class="hero-picture" style="grid-column:2;grid-row:1"><source media="(max-width:800px)" srcset="/assets/hero-mobile.jpg"><img class="hero-image" src="/assets/hero.jpg" alt="Model in an ivory and botanical print statement dress"></picture><div class="hero-copy" style="grid-column:1;grid-row:1"><div class="eyebrow">NEW COLLECTION</div><h1>Modern Nigerian<br>Elegance</h1><p>Timeless silhouettes for the woman who defines tomorrow.</p><div class="actions">${btn('Shop New In','shop/New','black')}${btn('Explore The Edit','runway','light')}</div></div></section><div class="trust">${[['NATIONWIDE DELIVERY','Reliable delivery across Nigeria'],['SECURE PAYMENTS','Safe and encrypted checkout'],['EASY RETURNS','Hassle-free returns'],['APPROVED REVIEWS','Real customers, verified orders']].map(([a,b])=>`<div><span class="trust-icon" data-trust-icon="${a}" aria-hidden="true"></span><div><strong>${a}</strong><small>${b}</small></div></div>`).join('')}</div>${link('Hi, I’m Verola. How can I help?','chat','assistant-link')}<section class="section"><div class="categories"><h2>Shop by Category</h2><div class="category-boxes">${[['Dresses','shop/Dresses'],['Sets & Tops','shop/Sets & Tops'],['Occasions','shop/Occasions'],['Journal','journal']].map(([t,r])=>link(t,r)).join('')}</div></div><div class="section-head"><div><h2>Featured Pieces</h2><p class="muted">Handpicked styles for your wardrobe</p></div>${link('View all','shop','text-link')}</div>${'<div class="featured-scroll" tabindex="0" role="region" aria-label="Featured pieces, automatically scrolling">'+grid(products,'five')+'</div>'}</section><section class="section" style="background:var(--white)"><div class="section-head"><h2>The Dress Edit</h2>${link('Explore the edit','gallery','text-link')}</div>${grid(products.filter(p=>p.category!=='Sets & Tops'))}</section>`}
function pills(values,selected,key='category'){return `<div class="pills ${key==='category'?'category':''}">${values.map(v=>action(v,'pick',`data-key="${key}" data-value="${esc(v)}" aria-pressed="${v===selected}"`,'pill '+(v===selected?'selected':''))).join('')}</div>`}
function filtered(){let ps=products.filter(p=>(state.category==='All'||(state.category==='New'?p.badge==='New':p.category===state.category))&&p.name.toLowerCase().includes(state.search.toLowerCase())&&p.price<=state.maxPrice&&(!state.filterColour||p.colour===state.filterColour));if(state.sort==='Price: Low to High')ps.sort((a,b)=>a.price-b.price);if(state.sort==='Price: High to Low')ps.sort((a,b)=>b.price-a.price);return ps}
const sortSelect=()=>`<select class="field" id="sort" aria-label="Sort products">${['Featured','Price: Low to High','Price: High to Low'].map(v=>`<option ${state.sort===v?'selected':''}>${v}</option>`).join('')}</select>`;
function shop(selecting=false){let ps=filtered();return `<div class="page">${heading(selecting?'Choose another piece':'Shop',selecting?'Your Fashion Lab preferences will stay the same.':`${ps.length} pieces · Dresses, sets and tops`)}${selecting?`<input id="catalog-search" class="field" placeholder="Search dresses, sets or tops…" aria-label="Search garments" value="${esc(state.search)}">`:''}<div class="mobile-shop-controls">${action('Filter','filter','','btn light')}${sortSelect()}</div><div class="shop-layout"><aside class="filters" id="filters"><h3>Filters</h3><div class="filter-group"><strong>CATEGORY</strong>${['Dresses','Sets & Tops','Occasions'].map(v=>`<label class="check"><input type="radio" name="category" data-category="${v}" ${state.category===v?'checked':''}>${v}</label>`).join('')}${action('All products','pick','data-key="category" data-value="All"','text-link')}</div><div class="filter-group"><strong>COLOUR</strong><div class="swatches">${Object.entries(colours).map(([c,h])=>action('','filter-colour',`style="--swatch:${h}" aria-label="Filter ${c}" data-colour="${c}"`,'swatch '+(state.filterColour===c?'selected':''))).join('')}</div></div><div class="filter-group"><strong>PRICE · Up to ${money(state.maxPrice)}</strong><input id="max-price" type="range" min="100000" max="250000" step="5000" value="${state.maxPrice}" aria-label="Maximum price"></div><div class="filter-group"><strong>SIZE</strong>${sizeButtons(state.filterSize,'filterSize')}</div>${action('Reset filters','reset-filters','','text-link')}</aside><div class="shop-results"><div class="section-head shop-products-heading"><h2>All Products <small>(${ps.length})</small></h2><div style="width:235px">${sortSelect().replace('id="sort"','id="desktop-sort"')}</div></div>${pills(['All','Dresses','Sets & Tops','Occasions'],state.category)}${ps.length?grid(ps,'',selecting?'select':''):`<div class="panel"><h2>No pieces match these filters</h2>${action('Reset filters','reset-filters','','btn')}</div>`}</div></div></div>`}
function sizeButtons(current,key='size'){return `<div class="sizes">${sizes.map(s=>action(s,'size',`data-key="${key}" data-value="${s}" aria-pressed="${current===s}"`,'size '+(current===s?'selected':''))).join('')}</div>`}
function swatches(){return `<div class="swatches">${Object.entries(colours).map(([c,h])=>action('','colour',`data-value="${c}" style="--swatch:${h}" aria-label="${c}" aria-pressed="${state.colour===c}"`,'swatch '+(state.colour===c?'selected':''))).join('')}</div>`}
function product(){const p=pby(param||state.selected);state.selected=p.id;return `<div class="page product-page"><p class="breadcrumb muted">${link('Shop','shop')} / ${p.category} / ${p.name}</p><div class="product-layout"><div class="product-gallery"><img class="product-main" src="${tall(p)}" alt="${p.name}"></div><div class="product-info"><h1>${p.name}</h1><div class="price">${money(p.price)}</div><p class="rating">★★★★★ &nbsp; 4.8 &nbsp; (24 reviews · design sample)</p><p class="description">A sculpted silhouette with a flattering waist, soft structure and an elegant evening finish.</p><label>Colour · ${p.colour}</label><div class="swatches"><span class="swatch selected" style="--swatch:${colours[p.colour]}"></span></div><div class="section-head"><label>Size</label>${link('Size guide','size-guide','text-link')}</div>${sizeButtons(state.size)}<p class="stock">● &nbsp; In stock · sample catalogue</p><div class="actions product-add">${action('Add to Bag','add',`data-id="${p.id}"`,'btn black wide')}${action(state.saved.includes(p.id)?'♥':'♡','save',`data-id="${p.id}" aria-label="Save ${p.name}"`,'btn light')}</div><div class="benefits"><div><strong>Free delivery</strong><small>Orders over ₦150,000</small></div><div><strong>Easy returns</strong><small>Within 7 days</small></div><div><strong>Secure checkout</strong><small>Your details are protected</small></div></div>${[['Product details','Premium structured fabric, concealed zip, elegant silhouette.'],['Fabric & care','Cold hand wash. Do not bleach. Steam on low heat.'],['Delivery & returns','Delivery fee calculated by state. Returns within 7 days.']].map(([t,d])=>`<details><summary>${t}</summary><p>${d}</p></details>`).join('')}<div class="actions" style="margin-top:25px">${btn('Style this piece','studio','small outline')}${btn('Compare with my photo','photo','small outline')}</div></div></div></div>`}
function empty(title,text,button='Browse the Shop'){return `<div class="empty"><div class="result-circle">♡</div><h1>${title}</h1><p class="muted">${text}</p>${btn(button,'shop','wide')}</div>`}
const subtotal=()=>state.bag.reduce((n,i)=>n+pby(i.id).price*i.qty,0);
function summary(delivery=false){return `<h2>Order Summary</h2><div class="summary-line"><span>Subtotal</span><strong>${money(subtotal())}</strong></div><div class="summary-line"><span>Delivery</span><span class="muted">${delivery?money(5000):'Calculated at checkout'}</span></div><div class="summary-line total"><span>Total</span><strong>${money(subtotal()+(delivery?5000:0))}</strong></div>`}
function bag(){return `<div class="page">${heading('Shopping Bag',`${state.bag.length} items`)}${!state.bag.length?empty('Your bag is empty','Discover a piece you’ll love.'): `<div class="split"><div>${state.bag.map((i,index)=>{const p=pby(i.id);return `<article class="bag-item">${link(`<img src="${tall(p)}" alt="${p.name}">`,'product/'+p.id)}<div class="item-info"><h3>${p.name}</h3><small>Size ${i.size} · ${p.colour}</small><div class="price">${money(p.price)}</div></div>${action('×','remove',`data-index="${index}" aria-label="Remove ${p.name}"`,'remove')}<div class="quantity">${action('−','quantity',`data-index="${index}" data-delta="-1" aria-label="Decrease quantity"`)}<span>${i.qty}</span>${action('+','quantity',`data-index="${index}" data-delta="1" aria-label="Increase quantity"`)}</div></article>`}).join('')}</div><div class="panel">${summary()}${btn('Proceed to Checkout','checkout','wide')}${btn('Continue Shopping','shop','light wide')}</div></div>`}</div>`}
function checkout(){if(!state.bag.length)return `<div class="page">${empty('Your bag is empty','Add a piece before checkout.')}</div>`;return `<div class="page">${heading('Checkout')}<div class="steps"><span class="step">1 &nbsp; Contact</span><span class="step">2 &nbsp; Delivery</span><span class="step">3 &nbsp; Review</span></div><form id="checkout-form"><div class="split"><div><h2>Contact Information</h2>${[['Email address','email','email','name@example.com'],['Full name','name','text','Amara Okafor'],['Phone number','phone','tel','0803 123 4567'],['Address','address','text','12 Admiralty Way'],['City / Area','city','text','Lekki Phase 1']].map(([t,n,tp,ph])=>`<label class="form-field"><span>${t}</span><input class="field" type="${tp}" name="${n}" placeholder="${ph}" autocomplete="${({email:'email',name:'name',phone:'tel',address:'street-address',city:'address-level2'})[n]}" required></label>`).join('')}<label class="form-field"><span>State</span><select name="state" class="field"><option>Lagos</option><option>Abuja</option><option>Delta</option><option>Akwa Ibom</option><option>Other</option></select></label></div><div><div class="panel"><div class="desktop-only">${state.bag.map(i=>{const p=pby(i.id);return `<div class="mini-item"><img src="${tall(p)}" alt="${p.name}"><div><h3>${p.name}</h3><small>Size ${i.size} · Qty ${i.qty}</small><p class="price">${money(p.price*i.qty)}</p></div></div>`}).join('')}</div>${summary(true)}</div><p class="muted" style="font-size:14px;margin-top:20px">Demo checkout. Your order is saved on this device; no payment is taken or request sent to the store.</p><button type="submit" class="btn wide">Submit Demo Order Request</button></div></div></form></div>`}
function confirmation(status=false){const o=state.order;if(!o)return `<div class="page">${heading('Order Status','No order saved on this device.')}${btn('Browse the Shop','shop')}</div>`;return `<div class="page narrow"><div class="panel confirmation"><div class="result-circle">✓</div><h1>${status?'Demo order saved':'Order request saved'}</h1><p class="muted">Thank you, ${esc(o.name.split(' ')[0])}. Your demo order is saved on this device. It has not been sent to the store.</p><div class="panel" style="background:var(--bg);text-align:left"><div class="summary-line"><div><small>Reference</small><p><strong>#${esc(o.ref)}</strong></p></div><div><small>Total</small><p class="price">${money(o.total)}</p></div></div></div>${btn(status?'Continue Shopping':'View Order Status',status?'shop':'order-status','wide')}${link('Continue Shopping','shop','text-link')}</div></div>`}
function saved(){return `<div class="page">${state.saved.length?heading('Saved Pieces',`${state.saved.length} favourites saved on this device.`)+grid(state.saved.map(pby),'five','saved'):empty('No saved pieces yet','Tap the heart on any product to keep it here for later.')}</div>`}
function colourRows(mode='colour'){return Object.entries(colours).map(([c,h])=>{const sel=mode==='prefs'?state.prefs.colours.includes(c):state.colour===c;return action(`<span class="swatch" style="--swatch:${h}"></span>${c}${sel?'<span class="tick">✓</span>':''}`,mode==='prefs'?'pref-colour':'colour',`data-value="${c}" aria-pressed="${sel}"`,'colour-row '+(sel?'selected':''))}).join('')}
function closet(){return `<div class="page">${heading('My Closet','Your saved garment references and style preferences on this device.')}<div class="closet"><div class="panel"><h2>Your preferences</h2>${[['Favourite colours',state.prefs.colours.join(' · ')],['Style',state.prefs.style],['Usual size',state.prefs.size],['Preferred fit',state.prefs.fit]].map(([a,b])=>`<div class="preference"><small>${a}</small><strong>${b}</strong></div>`).join('')}${btn('Edit Preferences','preferences','outline wide')}</div><div><h2>Saved garment references</h2>${state.refs.length?grid(state.refs.map(pby),'','refs'):`<p class="muted">Save a garment reference in Outfit Studio to keep it here.</p>${btn('Open Outfit Studio','studio')}`}</div></div></div>`}
function preferences(){return `<div class="page narrow">${heading('Edit preferences','These preferences stay on this device.')}<div class="group"><h3>Favourite colours</h3>${colourRows('prefs')}</div><div class="group"><h3>Style preference</h3>${pills(['Elegant & classic','Bold & modern','Minimal'],state.prefs.style,'prefs.style')}</div><div class="group"><h3>Usual size</h3>${sizeButtons(state.prefs.size,'prefs.size')}</div><div class="bottom-action">${action('Save Preferences','save-prefs','','btn wide')}</div></div>`}
const progress=()=>`<div class="progress">${['Occasion','Fit','Style','Setting','Budget','Request'].map((s,i)=>`<div><span>${i+1}</span>${s}</div>`).join('')}</div>`;
function lab(){return `<div class="page narrow">${heading('Build your styling profile','Tell us what you’re dressing for.')}${progress()}${[['Occasion','occasion',['Wedding','Dinner','Work','Brunch']],['Preferred fit','fit',['Fitted','Relaxed','Structured','Flowing']],['Style personality','style',['Elegant & classic','Bold & modern','Minimal','Romantic']],['Setting','setting',['Indoor','Outdoor','Daytime','Evening']]].map(([t,k,vs])=>`<div class="group"><h3>${t}</h3>${pills(vs,state.lab[k],'lab.'+k)}</div>`).join('')}<div class="bottom-action">${btn('Continue','lab-budget','wide')}</div></div>`}
function selectedGarment(){const p=pby(state.selected);return `<div class="panel selected-garment"><img src="${tall(p)}" alt="${p.name}"><div><h3>${p.name}</h3><p class="muted">${p.colour} · ${money(p.price)}</p><small>Selected garment</small></div>${link('Change','select','text-link')}</div>`}
function budget(){return `<div class="page narrow">${heading('Budget & request','Set your budget and tell Verola what you need.')}${progress()}<div class="group"><div class="section-head"><strong>Budget</strong><strong id="budget-value" style="color:var(--wine)">${money(state.lab.budget)}</strong></div><input id="budget" type="range" min="20000" max="250000" step="5000" value="${state.lab.budget}" aria-label="Styling budget"><div class="section-head"><small>₦20k</small><small>₦250k</small></div></div><label class="form-field"><span>Written styling request</span><textarea id="lab-request" class="field" placeholder="I want a sophisticated fitted look for a wedding in Lagos.">${esc(state.lab.request)}</textarea></label><div class="group"><h3>Garment to style around</h3>${selectedGarment()}</div>${action('Get Styling Recommendations','recommend','','btn wide bottom-action')}</div>`}
function labResults(){const ps=products.filter(p=>p.price<=state.lab.budget);return `<div class="page">${heading('Your Fashion Lab Edit',`${state.lab.occasion} · ${state.lab.fit} · ${state.lab.style} · ${state.lab.setting} · Budget ${money(state.lab.budget)}`)}<div class="panel"><div class="eyebrow">Verola’s styling direction · curated guidance</div><h2>${state.lab.style==='Bold & modern'?'Colour with confidence':'Polished modern elegance'}</h2><p class="muted">${state.lab.fit==='Relaxed'?'Keep the silhouette easy and balanced.':'Let one statement piece do the work.'} Pair warm metallic accessories with a clean heel and sleek hair.</p></div><section class="section" style="padding-left:0;padding-right:0"><h2>Recommended garments</h2>${ps.length?grid(ps,'','view'):`<p>No garments in this collection fit your budget.</p>${btn('Adjust Budget','lab-budget')}`}</section><h2>Complete the look</h2><div class="products" style="margin-top:22px">${[['Shoes','Minimal pointed heel'],['Bag','Structured mini bag'],['Jewellery','Gold drop earrings'],['Hair','Sleek low bun']].map(([a,b])=>`<div class="panel"><strong>${a}</strong><p class="muted">${b}</p></div>`).join('')}</div><p>${btn('Open Outfit Studio','studio')}</p></div>`}
function sizeGuide(){const rows=[['XS','78–82','60–64','86–90','Very fitted'],['S','83–87','65–69','91–95','Fitted'],['M','88–92','70–74','96–100','Regular'],['L','93–98','75–81','101–106','Relaxed'],['XL','99–105','82–88','107–113','Relaxed']];return `<div class="page narrow">${heading('Size Guide','Use your body measurements to choose the best fit. All measurements are in centimetres.')}<div class="table-wrap"><table><thead><tr>${['Size','Bust','Waist','Hips','Fit note'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div><h2>How to measure</h2>${[['Bust','Measure around the fullest part of your bust.'],['Waist','Measure around your natural waistline.'],['Hips','Measure around the fullest part of your hips.']].map(([a,b])=>`<div class="panel measure"><strong>${a}</strong><span class="muted">${b}</span></div>`).join('')}${btn('Use Size Estimate','estimate','wide bottom-action')}</div>`}
function estimate(result=false){if(result)return `<div class="page narrow">${heading('Your estimated size')}<div class="panel" style="text-align:center"><p class="muted">Recommended</p><div class="result-circle">${state.estimate}</div></div><p class="muted" style="text-align:center;margin:30px 0">Based on bust ${state.bust} cm and waist ${state.waist} cm</p><h2>Fit notes</h2>${[`Choose ${state.estimate} for the intended silhouette.`, 'If you prefer more ease, consider the next size.','Check the garment-specific size guide before ordering.'].map(t=>`<p class="panel">${t}</p>`).join('')}${action('Shop Size '+state.estimate,'shop-estimate','','btn wide')}</div>`;return `<div class="page narrow">${heading('Find your likely ZARELLE size','Enter your body measurements in centimetres. This is a basic estimate, not a tailoring measurement.')}<form id="estimate-form">${[['Bust','bust',state.bust],['Waist','waist',state.waist]].map(([a,b,c])=>`<label class="form-field"><span>${a} (cm)</span><input class="field" name="${b}" type="number" min="40" max="200" step="0.5" value="${c}" required></label>`).join('')}<div class="panel" style="margin-top:45px"><strong>How we estimate</strong><p class="muted">We compare your bust and waist against ZARELLE’s basic XS–XL guide and suggest the closest fit.</p></div><button class="btn wide bottom-action" type="submit">Estimate My Size</button></form><p style="text-align:center">${link('View full size guide','size-guide','text-link')}</p></div>`}
function photoUpload(){return `<div class="page narrow">${heading('Compare a garment with your photo','Your photo stays on this device and is not uploaded.')}<div class="panel upload"><div class="result-circle">+</div><h2>Add your photo</h2><p class="muted">JPG or PNG · stored locally in your browser session</p>${action('Choose Photo','upload','','btn')}</div><div class="group"><h2>Choose a garment</h2>${grid(products.slice(0,2),'two','select')}</div></div>`}
function comparison(colour=false,look=false){const p=pby(state.selected);return `<div class="page narrow">${heading(colour?'Compare colour effects':look?'Preview this look beside your photo':'Side-by-side preview',colour?'Compare colour swatches while keeping your photo in place.': 'See how the garment colour sits beside your own tones.')}<div class="comparison"><div>${state.photo?`<img src="${state.photo}" alt="Your uploaded photo">`:`<div class="photo-placeholder">${action('Add your photo','upload','','btn outline')}</div>`}<h3>Your photo</h3></div><div><img src="${tall(p)}" alt="${p.name}"><h3>${look?'Wedding Guest':p.name}</h3><strong>${money(p.price)}</strong></div></div>${colour?`<h3>Selected colour</h3><h2>${state.colour}</h2>${colourRows()}<p class="muted">Swatches are for comparison; the garment image shows its original colour.</p>`:look?'':`<h2>Preview garment colour</h2>${swatches()}${btn('Compare Colours','colour','outline')}`}<div class="actions" style="margin-top:30px">${action('Replace Photo','upload','','btn light wide')}${action('Remove Photo','remove-photo','','btn outline wide')}</div>${btn(look?'Shop Matching Pieces':'Open Outfit Studio',look?'look/'+state.selected:'studio','wide bottom-action')}</div>`}
function studio(){const p=pby(state.selected);return `<div class="page">${heading('Outfit Studio','Build the full look around your selected garment.')}<div class="outfit"><div class="panel outfit-garment"><img src="${tall(p)}" alt="${p.name}"><h3>${p.name}</h3><div class="price">${money(p.price)}</div><p class="muted">${p.colour} · Size ${state.size}</p>${action('Add Garment to Bag','add',`data-id="${p.id}"`,'btn wide')}${action(state.refs.includes(p.id)?'Remove garment reference':'Save garment reference','reference',`data-id="${p.id}"`,'text-link')}${link('Change garment','select','text-link')}</div><div><h2>Recommended pairings</h2>${[['SHOES','Pointed slingback','Cream leather','58,000','⌁'],['BAG','Structured mini bag','Deep brown','64,000','▣'],['JEWELLERY','Drop earrings','Warm gold','32,000','◇'],['HAIRSTYLE','Sleek low bun','Polished finish','Style note','✦']].map(([a,b,c,d,i])=>`<details class="panel" style="margin:20px 0"><summary style="display:flex;align-items:center;gap:24px"><span class="pairing-icon">${i}</span><span><span class="eyebrow" style="display:block;margin-bottom:12px">${a}</span><span style="font-size:24px">${b}</span></span></summary><p>${c} · ${d==='Style note'?d:'₦'+d}. Styling suggestion; accessory purchases are not available.</p></details>`).join('')}${action('Save This Outfit','save-outfit','','btn')}</div></div></div>`}
const looks=[['Wedding Guest','Soft structure, rich colour','amara','Wedding'],['City Dinner','Clean lines after dark','zuri','Dinner'],['Modern Occasion','Statement dressing','nia','Wedding'],['Office Chic','Sharp but feminine','lola','Work'],['Weekend Edit','Relaxed polish','kemi','Weekend'],['After Hours','Burgundy focus','amara','Dinner']];let galleryFilter='All Looks';
function gallery(){return `<div class="page">${heading('Style Gallery','Shoppable looks for weddings, work, evenings and everyday dressing.')}${pills(['All Looks','Wedding','Work','Dinner','Weekend'],galleryFilter,'gallery')}<div class="gallery">${looks.filter(l=>galleryFilter==='All Looks'||l[3]===galleryFilter).map(([a,b,id])=>`<article class="look">${link(`<img src="${tall(pby(id))}" alt="${a}" loading="lazy"><div class="look-caption"><h3>${a}</h3><small>${b}</small></div>`,'look/'+id)}</article>`).join('')}</div></div>`}
function look(){const p=pby(param);state.selected=p.id;const title=looks.find(l=>l[2]===p.id)?.[0]||'Wedding Guest';return `<div class="page narrow"><img src="${image(p)}" alt="${title}" style="aspect-ratio:1.4;margin-bottom:30px">${heading(title,'A polished look built around clean lines and rich colour.')}<h2>Matching pieces</h2>${grid([p,...products.filter(q=>q.id!==p.id).slice(0,1)],'two','view')}${btn('Preview with My Photo','look-preview','outline wide bottom-action')}</div>`}
function runway(){return `<section class="runway-hero"><div><div class="eyebrow">ZARELLE RUNWAY</div><h1>Collection 01 —<br>Modern Nigerian Elegance</h1><p>A study in silhouette, movement and evening light.</p>${btn('Explore Collection','shop','light')}</div></section><section class="section"><h2>Runway Looks</h2><p class="muted">Each look links directly to its product page.</p><div class="runway-products">${products.slice(0,4).map((p,i)=>`<article>${link(`<img src="${image(p)}" alt="${p.name}">`,'product/'+p.id)}<div><small style="color:var(--wine);font-weight:bold">Look 0${i+1}</small><h3>${p.name}</h3><p class="price">${money(p.price)}</p>${link('View product','product/'+p.id,'text-link')}</div></article>`).join('')}</div></section>`}
const articles=[['The New Nigerian Luxury Movement','kemi'],['5 Ways To Style Ankara Without Looking Traditional','amara'],['Behind The Collection','zuri'],['How Lagos Fashion Is Changing','nia'],['Modern African Elegance','lola']];
function journal(){return `<div class="page">${heading('Fashion Journal','Stories on modern African style, craft and culture.')}<div class="feature-story">${link('<img src="/assets/kemi.jpg" alt="Kemi Maxi Dress in a gold and ivory print">','article/0')}<div><div class="eyebrow">FEATURED STORY</div><h2>${articles[0][0]}</h2><p class="muted">How a new generation of designers and customers is reshaping contemporary Nigerian luxury.</p>${link('Read story','article/0','text-link')}</div></div><div class="journal-list">${articles.slice(1).map(([a,id],i)=>`<article>${link(`<img src="/assets/${id}.jpg" alt="${pby(id).name}">`,'article/'+(i+1))}<div><div class="eyebrow">STYLE JOURNAL</div><h3>${a}</h3>${link('Read article','article/'+(i+1),'text-link')}</div></article>`).join('')}</div></div>`}
function article(){const i=Math.min(4,Math.max(0,Number(param)||0)),a=articles[i];const copy=i===0?[['Luxury is becoming more personal.','For a growing generation of Nigerian fashion customers, luxury is not only about logos or formality. It is increasingly about fit, confidence, finishing and the feeling that a piece belongs to your life rather than simply to an occasion.'],['The shift is visible in colour, silhouette and styling.','Designers are balancing statement dressing with cleaner everyday pieces, while customers move comfortably between traditional references and globally modern wardrobes. The result is a fashion language that feels unmistakably African without being limited by one aesthetic.']]:i===1?[['Let one print lead.','Start with one Ankara piece and keep the rest of the outfit simple. A structured top with plain trousers gives the print room to stand out.'],['Five easy combinations','Try a printed skirt with a white shirt, a cropped jacket with denim, a maxi dress with simple heels, tailored trousers with a fitted top, or a printed blouse with a neutral skirt. Choose clean accessories and a fit that feels comfortable.']]:i===2?[['Silhouette comes first.','The collection brings together sculpted waists, soft sleeves and clean two-piece sets. Burgundy, ivory and emerald make each piece easy to style.'],['The finishing touches','A simple heel, a small structured bag and warm metallic jewellery complete the look without competing with the garment.']]:i===3?[['Dressing for a changing city','From a workday to dinner, a wardrobe needs pieces that move between settings. A coordinated set offers a clear starting point: wear it together or style the pieces separately.'],['Keep it personal','Choose the silhouette and colour you enjoy wearing. Add one thoughtful accessory and keep the rest comfortable enough for your day.']]:[['Modern African elegance','Clean tailoring and expressive colour can share the same wardrobe. A sculpted top or statement sleeve brings character to a simple outfit.'],['Build around one piece','Let the garment set the tone. A neutral shoe and understated jewellery make it easy to wear from one occasion to another.']];return `<div class="page"><article class="article"><div class="eyebrow">STYLE JOURNAL</div><h1>${a[0]}</h1><p class="muted">A closer look at the visual language, confidence and craft shaping contemporary Nigerian fashion.</p><small>ZARELLE Journal · ${i===0?'6':'3'} min read</small><img src="/assets/${i===0?'lola':a[1]}.jpg" alt="${pby(i===0?'lola':a[1]).name}"><div class="article-body">${copy.map(([t,p])=>`<h2>${t}</h2><p>${p}</p>`).join('')}<div class="panel bottom-action">${link('<strong>Explore the collection</strong><p class="muted">Shop pieces inspired by Modern African Elegance.</p>','shop')}</div></div></article></div>`}
function chat(){return `<div class="page"><div class="chat-layout"><aside class="chat-side"><div class="eyebrow">VEROLA</div><h2>Your fashion assistant</h2><p class="muted">Ask about products, sizing, delivery or styling.</p>${action('New conversation','new-chat','','btn wide')}${link('Product recommendations','shop')}${link('Sizing guidance','estimate')}${link('Delivery information','delivery')}${link('Order requests','order-status')}${link('Fashion Lab','lab')}</aside><div>${heading('Ask Verola','Personal fashion guidance for ZARELLE')}<div class="notice"><strong>AI temporarily unavailable</strong><p style="margin-bottom:0">You can still use ZARELLE’s predefined guidance below.</p></div><div class="chat-window"><div class="message"><strong>Hi, I’m Verola ✦</strong><p style="margin-bottom:0">I can guide you through this collection, size estimates and styling tools.</p></div><div id="messages">${state.messages.map(m=>`<div class="message ${m.user?'user':''}">${m.html||esc(m.text)}</div>`).join('')}</div><h2 style="font-size:25px;margin-top:30px">Choose a topic</h2><div class="pills">${['Product recommendations','What size should I get?','Tell me about delivery','Open Fashion Lab'].map(t=>action(t,'chat-topic',`data-value="${t}"`,'pill')).join('')}</div><form class="chat-form" id="chat-form"><input name="message" placeholder="Type your message…" aria-label="Message Verola" maxlength="500" required><button type="submit" aria-label="Send message">➤</button></form></div></div></div></div>`}
function delivery(){return `<div class="page narrow">${heading('Delivery & Returns','Delivery guidance shown in the supplied design.')}<div class="panel"><h2>Across Nigeria</h2><p>Delivery fees are calculated at checkout. The design uses ₦5,000 for Lagos and free delivery for orders over ₦150,000.</p><h2>Returns</h2><p>The design provides a 7-day return window. Confirm shipping rates, stock and return terms with the store before placing a real order.</p>${btn('Continue Shopping','shop')}</div></div>`}
function render(){const parts=location.hash.replace(/^#\/?/,'').split('/');route=parts[0]||'home';param=decodeURIComponent(parts.slice(1).join('/'));const routes={home,shop:()=>shop(),product,bag,checkout,confirmation,'order-status':()=>confirmation(true),saved,closet,preferences,lab,'lab-budget':budget,'lab-results':labResults,'size-guide':sizeGuide,estimate:()=>estimate(),'estimate-result':()=>estimate(true),photo:photoUpload,compare:()=>comparison(),colour:()=>comparison(true),'look-preview':()=>comparison(false,true),studio,gallery,look,runway,journal,article,chat,select:()=>shop(true),delivery};document.getElementById('app').innerHTML=shell((routes[route]||home)());document.getElementById('menu-links').innerHTML=navLinks()+[['Verola Chat','chat'],['Fashion Lab','lab'],['Photo Comparison','photo'],['Outfit Studio','studio'],['My Closet','closet'],['Runway','runway']].map(([t,r])=>link(t,r)).join('');window.setupSiteMotion?.();document.title=(titles[route]||({home:'Modern Nigerian Elegance',shop:'Shop',product:pby(param).name,bag:'Shopping Bag',checkout:'Checkout'})[route]||'ZARELLE')+' | ZARELLE';document.querySelectorAll('.icons a').forEach(a=>a.setAttribute('aria-label',a.hash.includes('saved')?'Saved pieces':a.hash.includes('chat')?'Verola chat':'Shopping bag'));}
function go(to){location.hash='/'+to}function toast(t){const el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.style.display='none',2800)}function setValue(key,v){if(key.includes('.')){const [a,b]=key.split('.');state[a][b]=v;persist(a)}else state[key]=v}
function add(id){const p=pby(id),item=state.bag.find(i=>i.id===p.id&&i.size===state.size);if(item)item.qty++;else state.bag.push({id:p.id,size:state.size,qty:1});persist('bag');render();toast(`${p.name} added to bag`)}
function guidance(t){state.messages.push({user:true,text:t});const lower=t.toLowerCase();let html='';if(/size|sizing|measure/.test(lower))html='Find your closest fit using your bust and waist measurements. '+btn('Use Size Estimate','estimate','small');else if(/deliver|return|shipping/.test(lower))html='Delivery and return guidance is available here. '+btn('Delivery & Returns','delivery','small');else if(/lab|styling/.test(lower))html='Choose an occasion, fit, style and budget to build your edit. '+btn('Open Fashion Lab','lab','small');else if(/order/.test(lower))html='Your demo orders are saved on this device. '+btn('View Order Status','order-status','small');else{const nums=lower.match(/[\d,]+/g);const budget=nums?Math.max(...nums.map(n=>Number(n.replaceAll(',','')))):250000;const ps=products.filter(p=>p.price<=budget&&(/top/.test(lower)?p.category==='Sets & Tops':/dress|wedding/.test(lower)?p.category!=='Sets & Tops':true));html=ps.length?'<p>These pieces match the collection and budget:</p>'+grid(ps.slice(0,3),'','view'):'There are no matching pieces in this collection. '+btn('Browse all pieces','shop','small')}state.messages.push({html});render();document.getElementById('messages')?.lastElementChild?.scrollIntoView({block:'nearest'})}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]');if(!a)return;const d=a.dataset;switch(d.action){case'menu':document.getElementById('menu').showModal();break;case'close-menu':document.getElementById('menu').close();break;case'save':{const i=state.saved.indexOf(d.id);if(i>=0)state.saved.splice(i,1);else state.saved.push(d.id);persist('saved');render();toast(i>=0?'Piece removed':'Piece saved');break}case'add':add(d.id);break;case'remove':state.bag.splice(Number(d.index),1);persist('bag');render();break;case'quantity':{const i=state.bag[Number(d.index)];i.qty+=Number(d.delta);if(i.qty<=0)state.bag.splice(Number(d.index),1);persist('bag');render();break}case'pick':if(d.key==='gallery')galleryFilter=d.value;else setValue(d.key,d.value);render();break;case'size':setValue(d.key,d.value);render();break;case'colour':state.colour=d.value;render();break;case'filter-colour':state.filterColour=state.filterColour===d.colour?'':d.colour;render();break;case'filter':document.getElementById('filters').classList.toggle('open');break;case'reset-filters':state.category='All';state.search='';state.maxPrice=250000;state.filterColour='';state.filterSize='';render();break;case'choose':state.selected=d.id;go(route==='photo'?'compare':(state.returnTo||'lab-budget'));break;case'pref-colour':{const i=state.prefs.colours.indexOf(d.value);if(i>=0)state.prefs.colours.splice(i,1);else state.prefs.colours.push(d.value);render();break}case'save-prefs':persist('prefs');go('closet');toast('Preferences saved');break;case'recommend':persist('lab');go('lab-results');break;case'shop-estimate':state.size=state.estimate;state.filterSize=state.estimate;go('shop');break;case'upload':document.getElementById('photo-file').click();break;case'remove-photo':if(state.photo)URL.revokeObjectURL(state.photo);state.photo=null;go('photo');break;case'reference':{const i=state.refs.indexOf(d.id);if(i>=0)state.refs.splice(i,1);else state.refs.push(d.id);persist('refs');render();toast(i>=0?'Reference removed':'Reference saved to My Closet');break}case'save-outfit':if(!state.refs.includes(state.selected))state.refs.push(state.selected);persist('refs');toast('Outfit saved to My Closet');break;case'chat-topic':guidance(d.value);break;case'new-chat':state.messages=[];render();break}});
document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&a.hash){document.getElementById('menu').close();if(a.hash==='#/select')state.returnTo=route==='photo'?'compare':route==='studio'?'studio':'lab-budget';if(a.hash==='#/photo')state.returnTo='compare'}});
document.addEventListener('input',e=>{if(e.target.id==='budget'){state.lab.budget=Number(e.target.value);document.getElementById('budget-value').textContent=money(state.lab.budget)}if(e.target.id==='lab-request')state.lab.request=e.target.value});
document.addEventListener('change',e=>{if(e.target.id==='sort'||e.target.id==='desktop-sort'){state.sort=e.target.value;render()}if(e.target.dataset.category){state.category=e.target.dataset.category;render()}if(e.target.id==='max-price'){state.maxPrice=Number(e.target.value);render()}if(e.target.id==='catalog-search'){state.search=e.target.value;render()}if(e.target.id==='photo-file'){const file=e.target.files[0];if(!file)return;if(!['image/jpeg','image/png'].includes(file.type)||file.size>15*1024*1024){toast('Choose a JPG or PNG under 15 MB');return}if(state.photo)URL.revokeObjectURL(state.photo);state.photo=URL.createObjectURL(file);if(route==='look-preview'||route==='compare')render();else go('compare');e.target.value=''}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);if(form.id==='search-form'){state.search=String(data.get('search'));state.category='All';if(route==='shop')render();else go('shop')}if(form.id==='chat-form')guidance(String(data.get('message')));if(form.id==='estimate-form'){state.bust=Number(data.get('bust'));state.waist=Number(data.get('waist'));const ranges=[[82,64],[87,69],[92,74],[98,81],[105,88]];let i=ranges.findIndex(([b,w])=>state.bust<=b&&state.waist<=w);if(i<0){toast('Measurements are outside the XS–XL guide. Check fit with the store.');return}state.estimate=sizes[i];go('estimate-result')}if(form.id==='checkout-form'){state.order={name:String(data.get('name')),total:subtotal()+5000,ref:'VEL-'+Date.now().toString().slice(-6),items:state.bag.map(i=>({...i})),created:new Date().toISOString()};persist('order');state.bag=[];persist('bag');go('confirmation')}});
function syncRoute(){const parts=location.hash.replace(/^#\/?/,'').split('/');if(parts[0]==='shop')state.category=parts[1]?decodeURIComponent(parts[1]):'All'}window.addEventListener('hashchange',()=>{syncRoute();render();window.scrollTo(0,0)});syncRoute();render();
